def graph_schema(url, name, kind, extra=None):
    graph = [
        {"@type": "WebPage", "@id": f"{url}#page", "url": url, "name": name, "about": {"@id": f"{BASE}/#business"}},
        {"@type": "BreadcrumbList", "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Home", "item": f"{BASE}/"},
            {"@type": "ListItem", "position": 2, "name": kind, "item": f"{BASE}/{kind.lower()}/"},
            {"@type": "ListItem", "position": 3, "name": name, "item": url},
        ]},
    ]
    if extra:
        graph.extend(extra)
    return {"@context": "https://schema.org", "@graph": graph}

