image_map = ['<?xml version="1.0" encoding="UTF-8"?>', '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">', f'  <url><loc>{BASE}/portfolio/</loc>']
for _, full, alt in portfolio_images:
    image_map.append(f'    <image:image><image:loc>{BASE}{full}</image:loc><image:title>{alt}</image:title><image:caption>{alt}, photographed by EyezLikeLenz.</image:caption></image:image>')
image_map.extend(['  </url>', '</urlset>'])
(ROOT / 'image-sitemap.xml').write_text('\n'.join(image_map) + '\n', encoding='utf-8')

print(f"Generated {len(SERVICES)} service pages, {len(STORIES)+1} story pages and the contact page")
